// N x N output-stationary systolic array. Row i is fed A[i][k] at cycle k+i, column j is fed B[k][j]
// at cycle k+j (skew generated by accel_top). PE(i,j) therefore sees A[i][k] and B[k][j] together at
// cycle k+i+j. All results are valid 3N-2 RUN cycles after the first feed.
`timescale 1ns/1ps
module systolic_array #(
    parameter N = 4
) (
    input                    clk,
    input                    rst_n,
    input                    clear,
    input                    en,
    input  [8*N-1:0]         a_edge,   // a_edge[8*i +: 8]   : left-edge input of row i
    input  [8*N-1:0]         b_edge,   // b_edge[8*j +: 8]   : top-edge input of column j
    output [32*N*N-1:0]      c_flat    // c_flat[32*(i*N+j) +: 32] = C[i][j]
);
    // a_bus: N rows x (N+1) columns ; value entering PE(i,j) is a_bus[(i*(N+1)+j)]
    // b_bus: (N+1) rows x N columns ; value entering PE(i,j) is b_bus[(i*N+j)]
    wire [8*N*(N+1)-1:0] a_bus;
    wire [8*(N+1)*N-1:0] b_bus;

    genvar i, j;
    generate
        for (i = 0; i < N; i = i + 1) begin : g_row_in
            assign a_bus[(i*(N+1))*8 +: 8] = a_edge[8*i +: 8];
        end
        for (j = 0; j < N; j = j + 1) begin : g_col_in
            assign b_bus[j*8 +: 8] = b_edge[8*j +: 8];
        end
        for (i = 0; i < N; i = i + 1) begin : g_r
            for (j = 0; j < N; j = j + 1) begin : g_c
                pe u_pe (
                    .clk  (clk),
                    .rst_n(rst_n),
                    .clear(clear),
                    .en   (en),
                    .a_in (a_bus[(i*(N+1)+j)*8 +: 8]),
                    .b_in (b_bus[(i*N+j)*8 +: 8]),
                    .a_out(a_bus[(i*(N+1)+j+1)*8 +: 8]),
                    .b_out(b_bus[((i+1)*N+j)*8 +: 8]),
                    .acc  (c_flat[32*(i*N+j) +: 32])
                );
            end
        end
    endgenerate
endmodule
